INSERT INTO public.products (category_id, name, slug, short_description, description, specs, images, price_ngn, compare_at_price_ngn, deposit_percent, stock, is_active, is_featured, is_subscription) VALUES
  ('4cf6ba61-24cf-418a-8e1c-9a0da020b5b0', 'WF 4-Channel PoE NVR (1TB)', 'wf-nvr-4ch-1tb', 'Enough recording for a small shop or flat — plug-and-play PoE.', '4 PoE ports, 1TB pre-installed drive, H.265+ compression, mobile app, HDMI+VGA out. Ships pre-configured — swap in the cameras and you''re live.', '{"hook_line": "Enough recording for a small shop or flat — plug-and-play PoE.", "features": ["Records 4 IP cams up to 4K", "1TB HDD (≈14 days motion)", "PoE powers cameras — one cable per cam", "Free mobile app, no subscription", "HDMI + VGA outputs"], "use_case": "Small retail, single-flat homes, boutique offices", "recommended_for": "Small shop / 3-4 bed home", "tech": {"channels": 4, "storage_tb": 1, "resolution": "4K", "ports": "4x PoE + 1 uplink", "compression": "H.265+", "warranty": "2 years"}, "image_brief": "Small black 4-channel NVR on a shelf with a single HDD visible."}'::jsonb, ARRAY[]::text[], 180000, NULL, 100, 15, true, false, false),
  ('4cf6ba61-24cf-418a-8e1c-9a0da020b5b0', 'WF 8-Channel PoE NVR (2TB)', 'wf-nvr-8ch-2tb-v2', 'The workhorse. 8 cameras, 2TB, PoE — most jobs end here.', 'Eight PoE ports, 2TB drive (~21 days at 8 cams), H.265+, dual-stream, phone push alerts. Our default recorder for houses and mid-size shops.', '{"hook_line": "The workhorse. 8 cameras, 2TB, PoE — most jobs end here.", "features": ["Runs 8 cameras up to 4K", "2TB HDD included", "Motion, line-cross, human/vehicle filter", "Dual-stream — smooth on phone data", "24V surge-protected power"], "use_case": "Most homes, small offices and retail with 5-8 cameras", "recommended_for": "Homes & small business", "tech": {"channels": 8, "storage_tb": 2, "resolution": "4K", "ports": "8x PoE + 1 uplink", "compression": "H.265+", "warranty": "2 years"}, "image_brief": "Black 1U NVR device with 8 PoE ports visible on the back."}'::jsonb, ARRAY[]::text[], 320000, NULL, 100, 15, true, false, false),
  ('4cf6ba61-24cf-418a-8e1c-9a0da020b5b0', 'WF 16-Channel PoE NVR (4TB)', 'wf-nvr-16ch-4tb-v2', 'For compounds, schools and larger sites that need 30+ days of footage.', '16 PoE ports, 4TB WD Purple drive, two SATA bays (expandable), H.265+, ONVIF, RAID-ready. Perfect middle ground for medium businesses.', '{"hook_line": "For compounds, schools and larger sites that need 30+ days of footage.", "features": ["16 cameras up to 4K", "4TB surveillance-grade HDD", "Two SATA bays — up to 20TB total", "AI motion filters (person/vehicle)", "Dual HDMI (4K + 1080p)"], "use_case": "Compounds, schools, medium businesses, apartment blocks", "recommended_for": "Compounds & schools", "tech": {"channels": 16, "storage_tb": 4, "bays": 2, "resolution": "4K", "warranty": "2 years"}, "image_brief": "Black 1U rack NVR with 16 PoE ports on the back and status LEDs."}'::jsonb, ARRAY[]::text[], 560000, NULL, 100, 15, true, false, false),
  ('4cf6ba61-24cf-418a-8e1c-9a0da020b5b0', 'WF 32-Channel PoE NVR (8TB)', 'wf-nvr-32ch-8tb', 'Serious kit for warehouses, estates and multi-building sites.', '32 channels, 8TB pre-installed across 2 bays, 4 total bays (up to 40TB), dual-NIC, RAID 1/5. Handles large deployments without stuttering.', '{"hook_line": "Serious kit for warehouses, estates and multi-building sites.", "features": ["32 cameras, up to 12MP", "8TB pre-installed (up to 40TB)", "RAID 1/5, dual-NIC failover", "AI face + license plate ready", "Rack-mount, 2U form"], "use_case": "Warehouses, estates, factories and multi-building sites", "recommended_for": "Warehouses & estates", "tech": {"channels": 32, "storage_tb": 8, "bays": 4, "resolution": "12MP", "form": "2U rack", "warranty": "3 years"}, "image_brief": "Larger 2U rack-mount NVR with front panel LEDs and drive bays."}'::jsonb, ARRAY[]::text[], 1050000, NULL, 100, 15, true, false, false),
  ('4cf6ba61-24cf-418a-8e1c-9a0da020b5b0', 'WF 64-Channel Enterprise NVR (16TB)', 'wf-nvr-64ch-16tb', 'Estate-scale recording without needing a server room.', '64 channels, 16TB across 4 bays (up to 64TB), 8 SATA bays optional, dual PSU, hot-swap drives, redundant NIC. Built to sit in a rack for years.', '{"hook_line": "Estate-scale recording without needing a server room.", "features": ["64 cameras, up to 12MP", "16TB pre-installed (up to 64TB)", "Hot-swap drives, dual PSU", "N+1 recording, ANR failover", "Rack-mount 2U enterprise chassis"], "use_case": "Estates, industrial parks, large campuses", "recommended_for": "Estates & campuses", "tech": {"channels": 64, "storage_tb": 16, "bays": 4, "psu": "Dual redundant", "warranty": "3 years"}, "image_brief": "Enterprise 2U NVR with hot-swap drive bays and dual PSUs on the back."}'::jsonb, ARRAY[]::text[], 2400000, NULL, 100, 8, true, true, false),
  ('4cf6ba61-24cf-418a-8e1c-9a0da020b5b0', 'WF 8-Channel HD Analogue DVR', 'wf-dvr-8ch-hd', 'Recycle existing analogue cameras — full HD, without rewiring.', 'Records existing analogue/AHD/CVI/TVI cameras up to 1080p over old coax, so you keep your cabling. 1TB drive included, hybrid IP support for 2 IP cams.', '{"hook_line": "Recycle existing analogue cameras — full HD, without rewiring.", "features": ["Reuses old coax cabling", "Records up to 1080p on analogue", "2x hybrid IP camera support", "1TB HDD included", "Free mobile viewing"], "use_case": "Sites with existing coax runs that don''t want to rewire", "recommended_for": "Retrofit installs", "tech": {"channels": 8, "storage_tb": 1, "analogue": "AHD/CVI/TVI/CVBS", "hybrid_ip": 2, "warranty": "2 years"}, "image_brief": "Small black hybrid DVR on a shelf with coax cables running out the back."}'::jsonb, ARRAY[]::text[], 165000, NULL, 100, 15, true, false, false),
  ('4cf6ba61-24cf-418a-8e1c-9a0da020b5b0', 'WF 16-Channel PoE+ NVR (No HDD)', 'wf-nvr-16ch-poe-plus', 'BYOD your own drives — for installers with stock on hand.', '16 PoE+ ports (max 200W), no HDD (bring your own), takes up to 2x 10TB drives. H.265+, ONVIF, HTML5 web UI. Great for installers who buy drives in bulk.', '{"hook_line": "BYOD your own drives — for installers with stock on hand.", "features": ["16 PoE+ ports, 200W budget", "No HDD — supply your own", "Takes 2x 10TB drives (20TB max)", "Full ONVIF, HTML5 UI", "Dual HDMI + VGA"], "use_case": "Installers who source their own storage", "recommended_for": "Installers", "tech": {"channels": 16, "storage_tb": 0, "poe_budget": "200W", "warranty": "2 years"}, "image_brief": "Black 1U NVR chassis with drive bays visible, no drives fitted."}'::jsonb, ARRAY[]::text[], 420000, NULL, 100, 15, true, false, false),
  ('4cf6ba61-24cf-418a-8e1c-9a0da020b5b0', 'WF 4-Channel Cloud NVR', 'wf-nvr-cloud-4ch', 'No local drive to worry about — footage lives in the cloud.', '4 cameras, no HDD, all recording pushed to encrypted cloud storage (subscription). Ideal for landlords who don''t want tenants near the recorder.', '{"hook_line": "No local drive to worry about — footage lives in the cloud.", "features": ["4 cameras, cloud-only recording", "Zero on-site storage to steal", "Rolling 7-day cloud retention included", "Upgrade to 30/90 days via subscription", "Works over 4G router"], "use_case": "Rental properties, remote sites, landlords", "recommended_for": "Landlords & remote sites", "tech": {"channels": 4, "storage": "Cloud (7-day incl.)", "warranty": "2 years"}, "image_brief": "Small white NVR without any drive bay, glowing status LED."}'::jsonb, ARRAY[]::text[], 145000, NULL, 100, 15, true, false, false),
  ('4cf6ba61-24cf-418a-8e1c-9a0da020b5b0', 'WF 8-Port PoE Switch (Expansion)', 'wf-nvr-poe-switch-8', 'Add 8 more cameras to any NVR without buying a bigger recorder.', 'Standalone 8-port PoE+ switch (120W budget) that feeds your existing NVR uplink. Cheaper way to grow from 8 to 16 cameras.', '{"hook_line": "Add 8 more cameras to any NVR without buying a bigger recorder.", "features": ["Adds 8 PoE cameras to any NVR", "120W total PoE budget", "Gigabit uplink", "Fanless, quiet operation", "Wall or rack-mountable"], "use_case": "Existing NVR owners expanding coverage", "recommended_for": "Expansion", "tech": {"ports": "8x PoE + 2 uplink", "poe_budget": "120W", "warranty": "2 years"}, "image_brief": "Small black 8-port PoE switch on a workbench."}'::jsonb, ARRAY[]::text[], 95000, NULL, 100, 15, true, false, false),
  ('4cf6ba61-24cf-418a-8e1c-9a0da020b5b0', 'WF 4K HDMI Video Decoder', 'wf-nvr-4k-decoder', 'Push a live 4-camera video wall to any HDMI TV.', 'Standalone decoder that pulls streams from your NVR and outputs a 2x2 or 3x3 video wall over HDMI. Turn any TV into a control-room monitor.', '{"hook_line": "Push a live 4-camera video wall to any HDMI TV.", "features": ["2x2, 3x3 or 4x4 layouts", "HDMI 4K output", "Works with any ONVIF NVR", "Web-based layout builder", "Loops through cameras automatically"], "use_case": "Reception desks, guardhouses, control rooms", "recommended_for": "Guardhouses", "tech": {"output": "HDMI 4K", "layouts": "1/4/9/16", "warranty": "2 years"}, "image_brief": "Small black decoder box connected to a large HDMI TV showing a 3x3 CCTV grid."}'::jsonb, ARRAY[]::text[], 185000, NULL, 100, 15, true, false, false),
  ('4cf6ba61-24cf-418a-8e1c-9a0da020b5b0', 'WF 1kVA UPS for NVR & Router', 'wf-nvr-ups-1kva', 'Keeps recording alive when the power goes.', 'Pure sine-wave 1000VA UPS sized for a small NVR + router + PoE switch. ~45 min runtime under typical load. AVR + surge protection.', '{"hook_line": "Keeps recording alive when the power goes.", "features": ["Pure sine-wave output", "~45 min runtime with typical NVR", "Auto voltage regulation (AVR)", "Surge + spike protection", "Cold-start capable"], "use_case": "Any NVR install in a Nigerian power environment", "recommended_for": "Every install", "tech": {"capacity": "1000VA / 600W", "runtime": "45 min typical", "warranty": "2 years"}, "image_brief": "Small black tower UPS with an LED display on the front, sitting on a shelf."}'::jsonb, ARRAY[]::text[], 125000, NULL, 100, 15, true, false, false),
  ('4cf6ba61-24cf-418a-8e1c-9a0da020b5b0', 'WF 4TB Surveillance HDD (WD Purple)', 'wf-nvr-hdd-4tb', 'Purpose-built for CCTV — 24/7 write, no crashes.', 'Genuine WD Purple 4TB drive, engineered for surveillance write loads (unlike desktop drives that die in 6 months). Drop-in for any NVR bay.', '{"hook_line": "Purpose-built for CCTV — 24/7 write, no crashes.", "features": ["24/7 CCTV workload rated", "Handles up to 64 camera streams", "3-year manufacturer warranty", "SATA 3, 3.5 inch", "Genuine WD Purple"], "use_case": "Any NVR drive upgrade or replacement", "recommended_for": "NVR upgrades", "tech": {"capacity_tb": 4, "model": "WD Purple", "warranty": "3 years"}, "image_brief": "Purple 3.5 inch hard drive labelled WD Purple on a workbench."}'::jsonb, ARRAY[]::text[], 68000, NULL, 100, 15, true, false, false),
  ('4cf6ba61-24cf-418a-8e1c-9a0da020b5b0', 'WF 8TB Surveillance HDD (WD Purple)', 'wf-nvr-hdd-8tb', 'Twice the retention, same reliable Purple platform.', 'WD Purple 8TB drive. Effectively doubles the retention window on any NVR without changing anything else in the install.', '{"hook_line": "Twice the retention, same reliable Purple platform.", "features": ["24/7 CCTV workload rated", "~30 days on an 8-camera system", "3-year manufacturer warranty", "SATA 3, 3.5 inch", "Genuine WD Purple"], "use_case": "Longer retention on existing NVRs", "recommended_for": "Longer retention", "tech": {"capacity_tb": 8, "model": "WD Purple", "warranty": "3 years"}, "image_brief": "Purple 3.5 inch hard drive labelled WD Purple 8TB on a workbench."}'::jsonb, ARRAY[]::text[], 128000, NULL, 100, 15, true, false, false),
  ('4cf6ba61-24cf-418a-8e1c-9a0da020b5b0', 'WF Complete 8-Camera Kit (NVR + 8 Bullet Cams + Drive)', 'wf-nvr-kit-8ch', 'One box, one price — the fastest way to get an 8-camera site live.', 'Includes our 8-channel 2TB NVR, 8x 4MP outdoor bullet cameras, 8x 20m network cables, brackets and connectors. Ships boxed and pre-linked.', '{"hook_line": "One box, one price — the fastest way to get an 8-camera site live.", "features": ["8-channel 2TB NVR pre-configured", "8x 4MP IP66 bullet cameras", "8x 20m Cat6 patch leads", "All brackets & fixings", "Free remote setup after install"], "use_case": "Full turnkey installs — one PO, one delivery", "recommended_for": "Turnkey installs", "tech": {"channels": 8, "cameras": 8, "resolution": "4MP", "warranty": "2 years"}, "image_brief": "Flat-lay of an NVR, 8 white bullet cameras, coils of cable and fittings on a workbench."}'::jsonb, ARRAY[]::text[], 895000, NULL, 50, 10, true, true, false),
  ('4cf6ba61-24cf-418a-8e1c-9a0da020b5b0', 'WF Complete 16-Camera Kit (NVR + 16 Cams + Drive)', 'wf-nvr-kit-16ch', 'Sixteen-camera coverage in a single order.', 'Our 16-channel 4TB NVR bundled with 16x 4MP cameras (mix of bullets and turrets), 20m leads and all mounting hardware. Ships boxed.', '{"hook_line": "Sixteen-camera coverage in a single order.", "features": ["16-channel 4TB NVR", "10x bullet + 6x turret cameras", "16x 20m Cat6 patch leads", "Full mounting hardware", "Free remote setup after install"], "use_case": "Larger homes, offices and small compounds", "recommended_for": "Compounds & offices", "tech": {"channels": 16, "cameras": 16, "resolution": "4MP", "warranty": "2 years"}, "image_brief": "Flat-lay of a 1U NVR, 16 cameras mixed bullet and turret, cables and fittings on a workbench."}'::jsonb, ARRAY[]::text[], 1750000, NULL, 50, 5, true, false, false),
  ('21ec5277-3eaf-4aa7-bcf7-49333015c791', 'Site 4G Solar Bullet Camera', 'wf-site-4g-solar-bullet', 'No power, no internet? This still records and streams live.', '4MP bullet camera with a built-in 4G SIM slot and 60W solar panel. Records to a 128GB SD card and streams over 4G. Ideal for construction sites and remote farms.', '{"hook_line": "No power, no internet? This still records and streams live.", "features": ["Built-in 4G — insert any SIM", "60W solar panel + battery included", "128GB SD card pre-installed", "Colour night vision to 30m", "IP66, works -20 to 60°C"], "use_case": "Construction sites, farms, land under development", "recommended_for": "Sites without power", "tech": {"resolution": "4MP", "connectivity": "4G LTE", "power": "Solar + battery", "storage": "128GB SD", "warranty": "2 years"}, "image_brief": "Large white bullet camera mounted on a solar pole overlooking a construction site."}'::jsonb, ARRAY[]::text[], 395000, NULL, 50, 10, true, true, false),
  ('21ec5277-3eaf-4aa7-bcf7-49333015c791', 'Site 4G Solar PTZ Camera', 'wf-site-4g-ptz', 'Pan, tilt and zoom a live site from your phone — no wiring needed.', '5MP PTZ with 20x optical zoom, 4G modem, dual 100W solar panels and a deep-cycle battery. Pre-set patrol routes for perimeter sweeps.', '{"hook_line": "Pan, tilt and zoom a live site from your phone — no wiring needed.", "features": ["20x optical zoom PTZ", "4G LTE with SIM slot", "Dual 100W solar + 100Ah battery", "Pre-set patrol routes", "Two-way audio siren"], "use_case": "Large construction sites, quarries, remote depots", "recommended_for": "Remote sites", "tech": {"resolution": "5MP", "zoom": "20x optical", "connectivity": "4G LTE", "power": "Solar 200W + 100Ah", "warranty": "2 years"}, "image_brief": "Large white PTZ camera on a tall pole with two solar panels above it, overlooking a quarry."}'::jsonb, ARRAY[]::text[], 895000, NULL, 50, 5, true, true, false),
  ('21ec5277-3eaf-4aa7-bcf7-49333015c791', 'Site Mobile Security Tower (4-Cam)', 'wf-site-tower-mobile', 'Wheel it in, deploy in 30 min, watch the whole site.', 'Trailer-mounted 6m mast with 4 cameras (2 fixed, 2 PTZ), solar + battery + 4G modem, floodlights and siren. Move between sites without a crane.', '{"hook_line": "Wheel it in, deploy in 30 min, watch the whole site.", "features": ["4 cameras (2 fixed, 2 PTZ)", "6m telescoping mast", "Solar + battery + 4G", "Floodlights + 110dB siren", "Trailer-mounted, towable"], "use_case": "Construction sites, events, temporary deployments", "recommended_for": "Construction & events", "tech": {"cameras": 4, "mast_m": 6, "power": "Solar + battery", "connectivity": "4G", "warranty": "2 years"}, "image_brief": "Trailer-mounted CCTV tower with tall mast and cameras deployed at a construction site."}'::jsonb, ARRAY[]::text[], 4900000, NULL, 30, 2, true, true, false),
  ('21ec5277-3eaf-4aa7-bcf7-49333015c791', 'Site Thermal Perimeter Camera', 'wf-site-thermal-perimeter', 'Sees people in pitch dark by their body heat — no light needed.', 'Thermal + optical dual-sensor bullet. Detects a human at 300m even in total darkness, smoke or fog. Ideal for perimeter fences and yards.', '{"hook_line": "Sees people in pitch dark by their body heat — no light needed.", "features": ["Thermal detection to 300m", "Dual optical + thermal sensors", "Works in total darkness, smoke, fog", "AI human/vehicle classification", "IP67, PoE++"], "use_case": "Perimeters, oil depots, warehouses at night", "recommended_for": "Perimeters", "tech": {"detection_m": 300, "sensors": "Thermal + optical", "protection": "IP67", "warranty": "3 years"}, "image_brief": "Grey bullet camera with two lens ports mounted on a perimeter fence at dusk."}'::jsonb, ARRAY[]::text[], 1250000, NULL, 50, 4, true, false, false),
  ('21ec5277-3eaf-4aa7-bcf7-49333015c791', 'Site ANPR / License Plate Camera', 'wf-site-anpr-camera', 'Reads plates day and night — logs every vehicle in and out.', '5MP bullet with a dedicated licence-plate lens, IR cut-off and onboard OCR. Captures plates up to 30m at 60 km/h. Exports CSV of every read.', '{"hook_line": "Reads plates day and night — logs every vehicle in and out.", "features": ["Captures plates day & night", "Onboard OCR — no PC needed", "Reads at up to 60 km/h", "Blacklist/whitelist alerts", "CSV + JSON export"], "use_case": "Estate gates, factory entrances, car parks", "recommended_for": "Estate & site gates", "tech": {"resolution": "5MP", "range_m": 30, "max_speed": "60 km/h", "warranty": "2 years"}, "image_brief": "Grey bullet camera with a specialised long lens, mounted on a boom at a gate."}'::jsonb, ARRAY[]::text[], 680000, NULL, 50, 6, true, false, false),
  ('21ec5277-3eaf-4aa7-bcf7-49333015c791', 'Site Blast-Proof Explosion-Rated Camera', 'wf-site-blast-proof', 'Certified for fuel depots, plants and hazardous zones.', 'Stainless-steel housed camera rated ATEX/IECEx for Zone 1/2 gas environments. 2MP starlight sensor, PoE, ONVIF. Serious kit for serious sites.', '{"hook_line": "Certified for fuel depots, plants and hazardous zones.", "features": ["ATEX/IECEx Zone 1/2 rated", "316L stainless-steel housing", "Starlight 2MP low-light sensor", "PoE + fibre option", "IP68, 5-year warranty"], "use_case": "Fuel depots, chemical plants, hazardous zones", "recommended_for": "Fuel & chemical", "tech": {"resolution": "2MP", "housing": "316L SS", "certification": "ATEX Zone 1/2", "warranty": "5 years"}, "image_brief": "Heavy stainless-steel cylindrical camera housing mounted on a pipe at an industrial plant."}'::jsonb, ARRAY[]::text[], 1650000, NULL, 30, 3, true, false, false),
  ('21ec5277-3eaf-4aa7-bcf7-49333015c791', 'Site Radar Intrusion Sensor', 'wf-site-radar-detect', 'Detects intruders before they reach the fence — 100m range.', '24GHz radar module that pairs with a PTZ to auto-track anything moving in a 100m x 90° zone. Ignores animals under 15kg. Works in rain and fog.', '{"hook_line": "Detects intruders before they reach the fence — 100m range.", "features": ["100m detection radius", "90° coverage zone", "Filters small animals", "Auto-slews any PTZ to target", "IP67, weather-proof"], "use_case": "Perimeter early-warning, oil & gas sites", "recommended_for": "Perimeters", "tech": {"range_m": 100, "fov": "90°", "frequency": "24GHz", "warranty": "2 years"}, "image_brief": "Grey box-shaped radar sensor mounted on a fence post next to a PTZ camera."}'::jsonb, ARRAY[]::text[], 480000, NULL, 100, 15, true, false, false),
  ('21ec5277-3eaf-4aa7-bcf7-49333015c791', 'Site Strobe & Siren Deterrent Light', 'wf-site-strobe-siren', 'Blinding strobe + 110dB siren — scares off intruders on sight.', 'IP66 strobe siren that pairs with any Hikvision or Dahua NVR. Triggers on motion or line-cross, burns for 15 s. Great deterrent alongside cameras.', '{"hook_line": "Blinding strobe + 110dB siren — scares off intruders on sight.", "features": ["110dB piezo siren", "LED strobe, 360° coverage", "Triggers on line-cross", "IP66, 12/24V DC", "Works with most NVRs"], "use_case": "Perimeters, gates, remote yards", "recommended_for": "Perimeters", "tech": {"db": 110, "strobe": "360° LED", "protection": "IP66", "warranty": "2 years"}, "image_brief": "White strobe-siren mounted high on a warehouse wall next to a floodlight."}'::jsonb, ARRAY[]::text[], 95000, NULL, 100, 15, true, false, false),
  ('21ec5277-3eaf-4aa7-bcf7-49333015c791', 'Site 30W Floodlight Camera', 'wf-site-floodlight-cam', 'Floods the area with white light and records in colour, all night.', '4MP camera with two 30W LED floodlights (5000 lumens). Motion-triggered, dusk-to-dawn schedule, colour night vision. Great for yards and driveways.', '{"hook_line": "Floods the area with white light and records in colour, all night.", "features": ["4MP + 5000 lumen floods", "Motion-triggered floodlights", "Full colour night vision", "Two-way talk + siren", "IP66, WiFi + Ethernet"], "use_case": "Yards, driveways, parking areas", "recommended_for": "Yards & driveways", "tech": {"resolution": "4MP", "lumens": 5000, "protection": "IP66", "warranty": "2 years"}, "image_brief": "Bullet camera with two large white LED floodlight panels either side, mounted on a wall."}'::jsonb, ARRAY[]::text[], 245000, NULL, 100, 15, true, false, false),
  ('21ec5277-3eaf-4aa7-bcf7-49333015c791', 'Site Long-Range PoE Extender (300m)', 'wf-site-poe-extender', 'Push PoE to 300m — no fibre, no local power at the camera.', 'PoE++ extender pair that lets you run a single Cat6 up to 300m to a remote camera and still power it. Saves fibre and inverter cost on perimeter runs.', '{"hook_line": "Push PoE to 300m — no fibre, no local power at the camera.", "features": ["Extends PoE to 300m over Cat6", "PoE++ (60W) throughput", "Weatherproof enclosure", "Plug-and-play, no config", "Two-year warranty"], "use_case": "Perimeter cameras far from the recorder", "recommended_for": "Long runs", "tech": {"range_m": 300, "poe": "PoE++ 60W", "warranty": "2 years"}, "image_brief": "Small black weatherproof PoE extender box mounted next to a pole camera."}'::jsonb, ARRAY[]::text[], 78000, NULL, 100, 15, true, false, false),
  ('21ec5277-3eaf-4aa7-bcf7-49333015c791', 'Site Outdoor 4G Router (IP67)', 'wf-site-4g-router-outdoor', 'Weather-proof 4G router — throw it up, insert SIM, done.', 'Outdoor-rated dual-SIM CAT6 4G router with PoE-in and PoE-out. Feeds power and internet to a remote camera cluster over a single Cat6 run.', '{"hook_line": "Weather-proof 4G router — throw it up, insert SIM, done.", "features": ["Dual-SIM CAT6 4G", "PoE-in and PoE-out", "IP67 outdoor housing", "Web + app management", "Two-year warranty"], "use_case": "Remote camera clusters over 4G", "recommended_for": "Remote clusters", "tech": {"category": "CAT6", "sims": 2, "protection": "IP67", "warranty": "2 years"}, "image_brief": "Small grey outdoor 4G router with antennas, mounted on a pole."}'::jsonb, ARRAY[]::text[], 210000, NULL, 100, 15, true, false, false),
  ('21ec5277-3eaf-4aa7-bcf7-49333015c791', 'Site 100Ah Lithium Site Battery', 'wf-site-battery-100ah', 'Runs a small camera cluster overnight without solar top-up.', '100Ah LiFePO4 battery in a weatherproof enclosure. Powers a 4-camera pole with router for ~24 h. Pairs with any solar controller.', '{"hook_line": "Runs a small camera cluster overnight without solar top-up.", "features": ["100Ah LiFePO4 (safe chemistry)", "~24h runtime for 4-cam pole", "IP65 weatherproof case", "BMS with over-charge protection", "5-year design life"], "use_case": "Solar pole cameras and remote stations", "recommended_for": "Solar poles", "tech": {"capacity_ah": 100, "chemistry": "LiFePO4", "protection": "IP65", "warranty": "3 years"}, "image_brief": "Grey weatherproof battery box on a concrete pad beside a solar CCTV pole."}'::jsonb, ARRAY[]::text[], 290000, NULL, 100, 15, true, false, false),
  ('21ec5277-3eaf-4aa7-bcf7-49333015c791', 'Site Guard Tour NFC Kit', 'wf-site-guard-tour-tag', 'Prove security guards actually did their rounds.', '10 x NFC checkpoint tags + a rugged NFC reader wand. Guards tap each checkpoint on their round; the wand logs time and location. Reports export to CSV.', '{"hook_line": "Prove security guards actually did their rounds.", "features": ["Rugged NFC reader wand", "10x weatherproof NFC tags", "Time-stamped patrol logs", "CSV/PDF report export", "IP65 tags, drop-tested wand"], "use_case": "Compounds and factories with roving guards", "recommended_for": "Guarded sites", "tech": {"tags": 10, "protection": "IP65", "warranty": "1 year"}, "image_brief": "Handheld NFC guard reader wand next to a weatherproof NFC tag on a compound wall."}'::jsonb, ARRAY[]::text[], 85000, NULL, 100, 15, true, false, false),
  ('21ec5277-3eaf-4aa7-bcf7-49333015c791', 'Site Perimeter Solar Kit — 6 Cameras', 'wf-site-perimeter-kit-6', 'Full six-camera perimeter kit for an off-grid compound.', '6x 4MP solar bullet cameras, a solar-fed 4G router hub, mounts and fixings. Deploys around a compound with no trenching or mains power.', '{"hook_line": "Full six-camera perimeter kit for an off-grid compound.", "features": ["6 solar-powered bullet cams", "Central 4G solar router", "All mounting brackets", "24-hour battery buffer", "Ships pre-configured"], "use_case": "Off-grid compounds and farm perimeters", "recommended_for": "Off-grid perimeters", "tech": {"cameras": 6, "connectivity": "4G", "power": "Solar", "warranty": "2 years"}, "image_brief": "Flat-lay of 6 white solar bullet cameras, a router hub, cables and brackets on a workbench."}'::jsonb, ARRAY[]::text[], 2450000, NULL, 50, 4, true, true, false),
  ('21ec5277-3eaf-4aa7-bcf7-49333015c791', 'Site ANPR Barrier Kit', 'wf-site-plate-barrier', 'Automatic boom barrier that opens for whitelisted plates only.', 'Boom barrier + ANPR camera + control PC. Whitelisted plates get in with no guard interaction. Guest QR codes handle deliveries and visitors.', '{"hook_line": "Automatic boom barrier that opens for whitelisted plates only.", "features": ["Automatic boom barrier", "ANPR camera with OCR", "Whitelist + guest QR access", "Alarm on blacklisted plate", "Free 6-month software support"], "use_case": "Estate and factory main gates", "recommended_for": "Estate gates", "tech": {"barrier": "3m boom", "warranty": "2 years"}, "image_brief": "Yellow-and-black boom barrier at an estate gate with an ANPR camera on a pole beside it."}'::jsonb, ARRAY[]::text[], 1750000, NULL, 30, 2, true, true, false),
  ('2b8b01c3-3358-4d65-8596-d340b69727ae', 'Solar 2MP Bullet Camera', 'wf-solar-2mp-bullet', 'Point it at a spot, walk away — powers itself forever.', '2MP bullet with an integrated 20W solar panel and 7.2Ah battery. Records to onboard SD and streams over WiFi or 4G. Perfect for remote gates.', '{"hook_line": "Point it at a spot, walk away — powers itself forever.", "features": ["Built-in 20W solar panel", "7.2Ah battery, 5-day autonomy", "4MP option available", "WiFi + optional 4G", "IP66 all-metal housing"], "use_case": "Remote gates, farms, unattended posts", "recommended_for": "Off-grid spots", "tech": {"resolution": "2MP", "solar_w": 20, "battery_ah": 7.2, "protection": "IP66", "warranty": "2 years"}, "image_brief": "White bullet camera with a small solar panel mounted directly above it, on a fence post."}'::jsonb, ARRAY[]::text[], 165000, NULL, 100, 15, true, false, false),
  ('2b8b01c3-3358-4d65-8596-d340b69727ae', 'Solar 4MP Bullet Camera', 'wf-solar-4mp-bullet', '4MP detail with true off-grid running.', 'Higher-resolution version of the 2MP solar bullet. 30W panel and 12Ah battery for 7-day autonomy in cloudy weather.', '{"hook_line": "4MP detail with true off-grid running.", "features": ["4MP true resolution", "30W solar panel", "12Ah LiFePO4 battery", "WiFi 5 + 4G-ready", "IP66, colour night vision"], "use_case": "Remote gates, boundaries, storage yards", "recommended_for": "Off-grid boundaries", "tech": {"resolution": "4MP", "solar_w": 30, "battery_ah": 12, "warranty": "2 years"}, "image_brief": "White 4MP bullet camera with a larger solar panel above it, mounted on a compound wall."}'::jsonb, ARRAY[]::text[], 215000, NULL, 100, 15, true, false, false),
  ('2b8b01c3-3358-4d65-8596-d340b69727ae', 'Solar 4MP PTZ Camera', 'wf-solar-4mp-ptz', 'Pan and tilt from your phone — off-grid, day and night.', '4MP PTZ with 4x optical zoom, 40W solar panel, 20Ah LiFePO4 battery. Auto patrol between preset points every 30 min.', '{"hook_line": "Pan and tilt from your phone — off-grid, day and night.", "features": ["4x optical zoom PTZ", "40W panel + 20Ah battery", "Auto patrol between presets", "Two-way audio + siren", "IP66"], "use_case": "Farms, storage yards, remote outposts", "recommended_for": "Off-grid overwatch", "tech": {"resolution": "4MP", "zoom": "4x", "solar_w": 40, "warranty": "2 years"}, "image_brief": "White solar PTZ camera on a pole with a 40W panel and battery box beside it, overlooking a farm."}'::jsonb, ARRAY[]::text[], 485000, NULL, 100, 15, true, false, false),
  ('2b8b01c3-3358-4d65-8596-d340b69727ae', 'Solar Dual-Lens Wide-Angle Camera', 'wf-solar-dual-lens', 'Two lenses stitched into one 180° panoramic feed — no blind spots.', 'Dual 2K sensors give you a stitched 180° view. 50W solar + 24Ah battery. Great for large driveways and yards where one camera has to see everything.', '{"hook_line": "Two lenses stitched into one 180° panoramic feed — no blind spots.", "features": ["Stitched 180° panoramic view", "Dual 2K sensors", "50W solar + 24Ah LiFePO4", "Human/vehicle AI detection", "IP66"], "use_case": "Large driveways, front yards, forecourts", "recommended_for": "Wide coverage", "tech": {"resolution": "2Kx2", "field": "180°", "solar_w": 50, "warranty": "2 years"}, "image_brief": "White dual-lens camera with two visible lens ports and a solar panel above, mounted on a pole."}'::jsonb, ARRAY[]::text[], 395000, NULL, 100, 15, true, false, false),
  ('2b8b01c3-3358-4d65-8596-d340b69727ae', 'Solar 4G Mini Cube Camera', 'wf-solar-4g-mini', 'Tiny 4G solar cam — hide it anywhere you need eyes.', 'Compact cube-style solar camera with a 4G SIM slot, magnetic mount and 5000mAh battery. Great for stakeouts, temporary sites and hidden points.', '{"hook_line": "Tiny 4G solar cam — hide it anywhere you need eyes.", "features": ["Compact stealth form-factor", "4G SIM slot", "5000mAh battery + solar top-up", "Magnetic mount included", "IP65"], "use_case": "Stakeouts, event coverage, temporary posts", "recommended_for": "Discreet coverage", "tech": {"resolution": "2MP", "battery_mah": 5000, "connectivity": "4G", "warranty": "2 years"}, "image_brief": "Small cube-shaped camera with a small solar panel, magnetically stuck to a metal beam."}'::jsonb, ARRAY[]::text[], 125000, NULL, 100, 15, true, false, false),
  ('2b8b01c3-3358-4d65-8596-d340b69727ae', 'Solar Floodlight + Camera Combo', 'wf-solar-flood-cam', 'Bright light plus a camera — both fully solar-powered.', '2 x 20W LED floodlights and a 4MP camera on one bracket. 80W solar panel and 30Ah battery keep both running through the night.', '{"hook_line": "Bright light plus a camera — both fully solar-powered.", "features": ["4MP camera + 40W flood", "80W solar + 30Ah battery", "Motion-triggered floods", "WiFi + 4G option", "IP66"], "use_case": "Driveways, yards and parking without mains", "recommended_for": "Off-grid lighting", "tech": {"resolution": "4MP", "lumens": 4000, "solar_w": 80, "warranty": "2 years"}, "image_brief": "White floodlight camera with two LED floods either side and a solar panel above, on a pole."}'::jsonb, ARRAY[]::text[], 345000, NULL, 100, 15, true, false, false),
  ('2b8b01c3-3358-4d65-8596-d340b69727ae', 'Solar Farm & Livestock Camera', 'wf-solar-farm-monitor', 'Watch the barn from your phone — no wiring across the fields.', 'Rugged 5MP camera on a 3m pole with 80W solar, 4G modem and battery. Preconfigured for livestock monitoring: person, vehicle and animal filters.', '{"hook_line": "Watch the barn from your phone — no wiring across the fields.", "features": ["5MP camera on 3m mast", "80W solar + 40Ah battery", "4G LTE built in", "Person/vehicle/animal filters", "IP67, temperature-hardened"], "use_case": "Farms, ranches, poultry compounds", "recommended_for": "Farms", "tech": {"resolution": "5MP", "mast_m": 3, "warranty": "2 years"}, "image_brief": "White bullet camera on a 3m pole with a solar panel and battery box, standing in a farm field."}'::jsonb, ARRAY[]::text[], 520000, NULL, 100, 15, true, false, false),
  ('2b8b01c3-3358-4d65-8596-d340b69727ae', 'Solar Fence-Line Perimeter Cam', 'wf-solar-fence-line', 'Fence-mount solar cam for long boundary runs.', '4MP bullet with a slim vertical solar panel that mounts to a fence post without needing a big pole. Meshes with other units for long runs.', '{"hook_line": "Fence-mount solar cam for long boundary runs.", "features": ["Fence-post form factor", "Slim vertical solar panel", "Mesh-links with other units", "4G-ready", "IP66"], "use_case": "Long boundary walls and fence lines", "recommended_for": "Fence lines", "tech": {"resolution": "4MP", "form": "Fence post", "warranty": "2 years"}, "image_brief": "White bullet camera on a slim vertical solar panel attached to a fence post."}'::jsonb, ARRAY[]::text[], 235000, NULL, 100, 15, true, false, false),
  ('2b8b01c3-3358-4d65-8596-d340b69727ae', 'Solar 30A MPPT Controller', 'wf-solar-controller-30a', 'Charge controller for building your own solar camera pole.', '30A MPPT solar charge controller with Bluetooth monitoring. Handles up to 400W of panels and any 12V/24V battery bank. Great for custom builds.', '{"hook_line": "Charge controller for building your own solar camera pole.", "features": ["30A MPPT (94% efficient)", "Handles up to 400W panels", "Bluetooth phone monitoring", "12V/24V auto-detect", "Low-voltage disconnect"], "use_case": "Installers building custom solar CCTV rigs", "recommended_for": "Custom rigs", "tech": {"amps": 30, "panel_max_w": 400, "warranty": "2 years"}, "image_brief": "Small black MPPT solar charge controller with LCD display, on a workbench."}'::jsonb, ARRAY[]::text[], 95000, NULL, 100, 15, true, false, false),
  ('2b8b01c3-3358-4d65-8596-d340b69727ae', 'Solar 100W Mono Panel', 'wf-solar-panel-100w', 'Extra panel for expanding an existing solar CCTV setup.', '100W monocrystalline panel with 25-year output warranty. Bolt onto an existing pole to add capacity or shorten winter downtime.', '{"hook_line": "Extra panel for expanding an existing solar CCTV setup.", "features": ["100W monocrystalline", "25-year power output warranty", "Aluminium frame, tempered glass", "MC4 connectors", "Plug-and-play with any controller"], "use_case": "Adding capacity to existing solar CCTV poles", "recommended_for": "Add-on capacity", "tech": {"watts": 100, "type": "Monocrystalline", "warranty": "25 years (output)"}, "image_brief": "Rectangular blue-black 100W solar panel resting against a shed wall."}'::jsonb, ARRAY[]::text[], 78000, NULL, 100, 15, true, false, false),
  ('2b8b01c3-3358-4d65-8596-d340b69727ae', 'Solar 50Ah LiFePO4 Battery', 'wf-solar-battery-50ah', 'Purpose-sized battery for a solar CCTV pole.', '50Ah LiFePO4 battery — the sweet spot for a single-camera solar pole. 2000+ cycle life, integrated BMS. Fits our weatherproof battery boxes.', '{"hook_line": "Purpose-sized battery for a solar CCTV pole.", "features": ["50Ah LiFePO4", "2000+ cycle life", "Integrated BMS", "Cold-weather charging", "5-year design life"], "use_case": "Single-camera solar poles", "recommended_for": "Solar poles", "tech": {"capacity_ah": 50, "chemistry": "LiFePO4", "warranty": "3 years"}, "image_brief": "Grey 50Ah battery unit with visible terminals on a workbench."}'::jsonb, ARRAY[]::text[], 165000, NULL, 100, 15, true, false, false),
  ('2b8b01c3-3358-4d65-8596-d340b69727ae', 'Solar 3m Camera Pole (Complete)', 'wf-solar-pole-3m', 'Ready-made 3m pole for mounting solar cameras.', 'Powder-coated 3m steel pole with pre-drilled panel bracket, battery box mount and camera arm. Comes with base plate and anchor bolts.', '{"hook_line": "Ready-made 3m pole for mounting solar cameras.", "features": ["3m powder-coated steel pole", "Panel + battery box brackets", "Base plate + anchors included", "Cable channel inside pole", "Rated for 60W panel + camera"], "use_case": "Solar camera installs on open ground", "recommended_for": "Open sites", "tech": {"height_m": 3, "finish": "Powder-coated", "warranty": "2 years"}, "image_brief": "Grey 3m steel pole standing on a concrete base with brackets for a solar panel and camera arm."}'::jsonb, ARRAY[]::text[], 120000, NULL, 100, 15, true, false, false),
  ('2b8b01c3-3358-4d65-8596-d340b69727ae', 'Solar 6m Site Camera Mast', 'wf-solar-pole-6m', 'Tall 6m mast for wide-area overwatch.', '6m sectional steel mast with cable channel and pre-drilled brackets for a 100W panel, battery box and PTZ or dual-cam head. Site-friendly base plate.', '{"hook_line": "Tall 6m mast for wide-area overwatch.", "features": ["6m sectional mast", "Handles 100W panel + PTZ", "Cable channel inside mast", "Site-friendly base plate", "Two-person install"], "use_case": "Site perimeters and long-range overwatch", "recommended_for": "Site perimeters", "tech": {"height_m": 6, "warranty": "2 years"}, "image_brief": "Tall 6m grey steel mast with brackets, standing on a concrete base at a construction site."}'::jsonb, ARRAY[]::text[], 295000, NULL, 100, 15, true, false, false),
  ('2b8b01c3-3358-4d65-8596-d340b69727ae', 'Solar Kit — 2-Camera Compound', 'wf-solar-kit-2cam', 'Ready-to-install 2-camera solar kit for a small compound.', '2x 4MP solar bullet cameras + 4G router hub + all mounts. Deploys around a small compound corner-to-corner without any wiring.', '{"hook_line": "Ready-to-install 2-camera solar kit for a small compound.", "features": ["2x 4MP solar bullet cams", "Central 4G solar router", "All brackets, no wiring", "24h battery buffer", "Ships pre-linked"], "use_case": "Small compounds without mains at the corners", "recommended_for": "Small compounds", "tech": {"cameras": 2, "warranty": "2 years"}, "image_brief": "Flat-lay of two white solar bullet cameras, a small router hub and brackets on a workbench."}'::jsonb, ARRAY[]::text[], 425000, NULL, 50, 8, true, false, false),
  ('2b8b01c3-3358-4d65-8596-d340b69727ae', 'Solar Kit — 4-Camera Compound', 'wf-solar-kit-4cam', '4-camera solar kit for a medium compound perimeter.', '4x 4MP solar bullet cameras, a solar-fed 4G router and central battery buffer. Everything you need for a full perimeter without trenching.', '{"hook_line": "4-camera solar kit for a medium compound perimeter.", "features": ["4x 4MP solar bullet cams", "Central 4G router hub", "Central battery buffer", "Full mounting hardware", "Free remote setup after install"], "use_case": "Medium compounds and farms", "recommended_for": "Medium compounds", "tech": {"cameras": 4, "warranty": "2 years"}, "image_brief": "Flat-lay of 4 white solar bullet cameras, a router hub, battery box, cables and brackets on a workbench."}'::jsonb, ARRAY[]::text[], 825000, NULL, 50, 6, true, true, false),
  ('1f363d83-18a8-4cc9-8eff-a5d5f9648f8a', 'IP 2MP Outdoor Bullet', 'wf-ip-2mp-bullet', 'Cheap, cheerful and sharp enough for a driveway.', 'Entry-level 2MP IP bullet camera. PoE, ONVIF, H.265+. Perfect for filling in gaps around an existing NVR without breaking the budget.', '{"hook_line": "Cheap, cheerful and sharp enough for a driveway.", "features": ["2MP full HD (1080p)", "PoE + ONVIF", "30m IR night vision", "H.265+ compression", "IP66"], "use_case": "Budget IP camera fills — driveways, side walls", "recommended_for": "Budget fill", "tech": {"resolution": "2MP", "protection": "IP66", "warranty": "2 years"}, "image_brief": "Small white bullet camera on a wall bracket, aimed at a driveway."}'::jsonb, ARRAY[]::text[], 42000, NULL, 100, 15, true, false, false),
  ('1f363d83-18a8-4cc9-8eff-a5d5f9648f8a', 'IP 4MP Outdoor Bullet', 'wf-ip-4mp-bullet', 'Our default outdoor camera — the one we install most.', '4MP bullet with H.265+, 30m IR range, IP66. Sharp enough to make out faces at the gate and cheap enough to buy in multiples.', '{"hook_line": "Our default outdoor camera — the one we install most.", "features": ["4MP true resolution", "30m IR night vision", "H.265+ compression", "PoE + 12V DC", "IP66"], "use_case": "General outdoor use — driveways, side walls, gates", "recommended_for": "Homes & offices", "tech": {"resolution": "4MP", "protection": "IP66", "warranty": "2 years"}, "image_brief": "White bullet camera on a wall bracket, aimed at a driveway."}'::jsonb, ARRAY[]::text[], 68000, NULL, 100, 25, true, true, false),
  ('1f363d83-18a8-4cc9-8eff-a5d5f9648f8a', 'IP 4MP Indoor Dome', 'wf-ip-4mp-dome', 'Discreet ceiling dome for shops, offices and receptions.', 'Compact 4MP dome, plastic housing, 20m IR, PoE. Blends into a ceiling and doesn''t scream ''CCTV'' at customers.', '{"hook_line": "Discreet ceiling dome for shops, offices and receptions.", "features": ["4MP true resolution", "20m IR night vision", "Plastic ceiling dome", "PoE + 12V DC", "H.265+"], "use_case": "Shops, offices, receptions, indoor corridors", "recommended_for": "Indoor use", "tech": {"resolution": "4MP", "protection": "IP20 (indoor)", "warranty": "2 years"}, "image_brief": "White ceiling dome camera on an office ceiling."}'::jsonb, ARRAY[]::text[], 65000, NULL, 100, 15, true, false, false),
  ('1f363d83-18a8-4cc9-8eff-a5d5f9648f8a', 'IP 4MP Outdoor Turret', 'wf-ip-4mp-turret', 'Rain-proof turret for tighter angles.', '4MP turret (eyeball) — easier to aim into corners than a dome. IP67, PoE, colour night vision. Great for shopfronts and doorways.', '{"hook_line": "Rain-proof turret for tighter angles.", "features": ["4MP colour night vision", "IP67 outdoor rated", "Adjustable eyeball head", "PoE + 12V DC", "H.265+"], "use_case": "Shopfronts, entryways, tighter corners", "recommended_for": "Doorways", "tech": {"resolution": "4MP", "protection": "IP67", "warranty": "2 years"}, "image_brief": "White outdoor turret camera on a shopfront awning."}'::jsonb, ARRAY[]::text[], 78000, NULL, 100, 15, true, false, false),
  ('1f363d83-18a8-4cc9-8eff-a5d5f9648f8a', 'IP 5MP Colour-Night Bullet', 'wf-ip-5mp-bullet', 'Full-colour footage at night, no floodlight needed.', '5MP bullet with a starlight sensor and small warm-white LED. Records in colour down to 0.005 lux — much better than IR grayscale.', '{"hook_line": "Full-colour footage at night, no floodlight needed.", "features": ["5MP starlight sensor", "Colour night vision to 30m", "Warm-white LED, no bug swarm", "PoE + 12V DC", "IP67"], "use_case": "Sites where you need to see colours of vehicles and clothing", "recommended_for": "Night colour", "tech": {"resolution": "5MP", "min_lux": 0.005, "warranty": "2 years"}, "image_brief": "White bullet camera with a small visible LED, mounted above a shop entrance at night."}'::jsonb, ARRAY[]::text[], 115000, NULL, 100, 15, true, false, false),
  ('1f363d83-18a8-4cc9-8eff-a5d5f9648f8a', 'IP 8MP 4K Bullet', 'wf-ip-8mp-4k-bullet', 'Zoom in on the footage — the pixels are still there.', '8MP (4K) bullet. Zoom into a face across a compound and it stays sharp. Great for gates and driveways where identification matters.', '{"hook_line": "Zoom in on the footage — the pixels are still there.", "features": ["8MP (4K) resolution", "50m IR range", "Zoom-in-post friendly", "PoE + 12V DC", "IP67"], "use_case": "Gates, driveways and long approaches", "recommended_for": "Identification", "tech": {"resolution": "8MP", "protection": "IP67", "warranty": "2 years"}, "image_brief": "Large white bullet camera on a wall aimed at a compound gate."}'::jsonb, ARRAY[]::text[], 165000, NULL, 100, 15, true, false, false),
  ('1f363d83-18a8-4cc9-8eff-a5d5f9648f8a', 'IP 8MP 4K Turret', 'wf-ip-8mp-4k-turret', '4K turret for shopfronts that want serious pixel density.', '4K turret camera. Records fine facial detail at counter distance. IP67, PoE, H.265+. Colour night vision option.', '{"hook_line": "4K turret for shopfronts that want serious pixel density.", "features": ["8MP (4K) resolution", "30m IR range", "Colour night vision option", "PoE + 12V DC", "IP67"], "use_case": "Retail shopfronts, tellers, luxury retail", "recommended_for": "Retail", "tech": {"resolution": "8MP", "protection": "IP67", "warranty": "2 years"}, "image_brief": "White turret camera on a shop ceiling with wooden shelves behind it."}'::jsonb, ARRAY[]::text[], 175000, NULL, 100, 15, true, false, false),
  ('1f363d83-18a8-4cc9-8eff-a5d5f9648f8a', 'IP 6MP Fisheye Ceiling Cam', 'wf-ip-fisheye-6mp', 'One camera, whole room — 360° coverage from a single ceiling point.', '6MP fisheye camera that gives a full 360° dewarped view. One camera replaces four in an open room. PoE, ONVIF.', '{"hook_line": "One camera, whole room — 360° coverage from a single ceiling point.", "features": ["6MP full 360° coverage", "Dewarps in NVR or app", "Replaces 4 corner cameras", "PoE + 12V DC", "IP20 (indoor)"], "use_case": "Open-plan offices, retail floors, warehouses", "recommended_for": "Open-plan rooms", "tech": {"resolution": "6MP", "fov": "360°", "warranty": "2 years"}, "image_brief": "White ceiling-mounted fisheye camera with a hemispherical lens, on a warehouse ceiling."}'::jsonb, ARRAY[]::text[], 195000, NULL, 100, 15, true, false, false),
  ('1f363d83-18a8-4cc9-8eff-a5d5f9648f8a', 'IP 8MP Multi-Sensor Panoramic', 'wf-ip-panoramic-8mp', 'Four sensors, one camera — stitched 180° panoramic view.', 'Four 2MP sensors give a combined 180° panoramic feed at 8MP total. One PoE cable does the work of four cameras in front of a compound.', '{"hook_line": "Four sensors, one camera — stitched 180° panoramic view.", "features": ["4 stitched 2MP sensors", "180° panoramic view", "Single PoE cable", "Recorded as one channel", "IP67"], "use_case": "Compound fronts, forecourts, wide entrances", "recommended_for": "Wide fronts", "tech": {"resolution": "8MP", "sensors": 4, "fov": "180°", "warranty": "2 years"}, "image_brief": "White panoramic camera with four visible lens ports arranged in a curve, mounted on a wall."}'::jsonb, ARRAY[]::text[], 395000, NULL, 100, 15, true, false, false),
  ('1f363d83-18a8-4cc9-8eff-a5d5f9648f8a', 'IP 4MP Audio Bullet', 'wf-ip-audio-mic-bullet', 'Records what people say, not just what they do.', '4MP bullet with a high-quality built-in microphone and two-way audio speaker. Great for gates and reception areas where you need to talk to visitors.', '{"hook_line": "Records what people say, not just what they do.", "features": ["Built-in microphone", "Two-way audio speaker", "Human voice enhancement", "PoE + 12V DC", "IP66"], "use_case": "Gates, receptions, drive-through counters", "recommended_for": "Two-way talk", "tech": {"resolution": "4MP", "audio": "Two-way", "warranty": "2 years"}, "image_brief": "White bullet camera with a visible microphone port near the lens, on a gate post."}'::jsonb, ARRAY[]::text[], 95000, NULL, 100, 15, true, false, false),
  ('1f363d83-18a8-4cc9-8eff-a5d5f9648f8a', 'IP 2MP Mini Bullet', 'wf-ip-mini-2mp', 'Tiny form factor — hides in door frames and shop signs.', 'Very compact 2MP bullet only 12cm long. Blends into doorframes and shop signs. Standard PoE, ONVIF.', '{"hook_line": "Tiny form factor — hides in door frames and shop signs.", "features": ["Compact 12cm form factor", "2MP full HD", "PoE + ONVIF", "20m IR range", "IP66"], "use_case": "Places where a full-size bullet is too obvious", "recommended_for": "Discreet mounts", "tech": {"resolution": "2MP", "length_cm": 12, "warranty": "2 years"}, "image_brief": "Small white mini bullet camera mounted inside a doorframe."}'::jsonb, ARRAY[]::text[], 55000, NULL, 100, 15, true, false, false),
  ('1f363d83-18a8-4cc9-8eff-a5d5f9648f8a', 'IP 2MP Pinhole Covert Cam', 'wf-ip-hidden-pinhole', 'Barely visible — great for retail loss-prevention.', 'Two-part pinhole covert camera: a tiny lens head connected to a hidden body. Fits behind a wall or ceiling with only a 5mm hole visible.', '{"hook_line": "Barely visible — great for retail loss-prevention.", "features": ["Tiny 5mm exposed lens", "Hidden main body", "2MP full HD", "PoE via main body", "Great for LP investigations"], "use_case": "Loss prevention, discreet investigations", "recommended_for": "Loss prevention", "tech": {"resolution": "2MP", "exposed_mm": 5, "warranty": "2 years"}, "image_brief": "Small pinhole lens embedded in a ceiling tile, with a discreet cable running away."}'::jsonb, ARRAY[]::text[], 148000, NULL, 100, 15, true, false, false),
  ('1f363d83-18a8-4cc9-8eff-a5d5f9648f8a', 'IP 2MP ATEX Zone 2 Camera', 'wf-ip-explosion-atex-cam', 'Certified safe for hazardous fuel and chemical zones.', '2MP starlight IP camera in a stainless housing, ATEX/IECEx Zone 2 rated. Cheaper than the Zone 1 blast-proof unit for less-severe environments.', '{"hook_line": "Certified safe for hazardous fuel and chemical zones.", "features": ["ATEX/IECEx Zone 2 rated", "316 stainless steel housing", "Starlight low-light sensor", "PoE + fibre option", "IP68"], "use_case": "Petrol stations, mid-hazard chemical areas", "recommended_for": "Fuel & mid-hazard", "tech": {"resolution": "2MP", "housing": "316 SS", "certification": "ATEX Zone 2", "warranty": "5 years"}, "image_brief": "Stainless steel cylindrical camera housing mounted at a petrol station canopy."}'::jsonb, ARRAY[]::text[], 1250000, NULL, 50, 3, true, false, false),
  ('1f363d83-18a8-4cc9-8eff-a5d5f9648f8a', 'IP 160x120 Thermal Bullet', 'wf-ip-thermal-160', 'Sees people in complete darkness by body heat.', 'Entry-level thermal IP camera — 160x120 sensor, detects a person at 60m in total darkness or smoke. Pairs with any ONVIF NVR.', '{"hook_line": "Sees people in complete darkness by body heat.", "features": ["160x120 thermal sensor", "Detects person at 60m", "Works in total darkness", "Smoke/fog penetration", "PoE + ONVIF"], "use_case": "Perimeters, warehouses, blackout monitoring", "recommended_for": "Blackout security", "tech": {"resolution": "160x120 thermal", "range_m": 60, "warranty": "3 years"}, "image_brief": "Grey bullet camera with a distinctive thermal lens, mounted on a warehouse wall."}'::jsonb, ARRAY[]::text[], 680000, NULL, 50, 4, true, false, false),
  ('1f363d83-18a8-4cc9-8eff-a5d5f9648f8a', 'IP 4-Camera PoE Kit', 'wf-ip-kit-4-poe', '4 x 4MP IP bullets ready to plug into any 4-port PoE NVR.', 'Four 4MP outdoor bullets with 4x 20m Cat6 leads and brackets. Just plug into your existing PoE NVR — no configuration needed.', '{"hook_line": "4 x 4MP IP bullets ready to plug into any 4-port PoE NVR.", "features": ["4x 4MP outdoor bullet cams", "4x 20m Cat6 leads", "All brackets & fixings", "Plug-and-play with WF NVRs", "2 year warranty on cameras"], "use_case": "Expanding or completing a PoE NVR install", "recommended_for": "PoE install kit", "tech": {"cameras": 4, "resolution": "4MP", "warranty": "2 years"}, "image_brief": "Flat-lay of 4 white bullet cameras, coils of network cable and brackets on a workbench."}'::jsonb, ARRAY[]::text[], 245000, NULL, 50, 10, true, false, false),
  ('19588e06-3048-466b-b2bf-8c59ed68c1e0', 'PTZ 4MP 4x Mini Dome', 'wf-ptz-4mp-4x-mini', 'Compact pan-tilt-zoom dome for indoor overwatch.', 'Small 4MP mini PTZ with 4x optical zoom. Discreet enough for a shop ceiling, powerful enough to zoom into a face across the room.', '{"hook_line": "Compact pan-tilt-zoom dome for indoor overwatch.", "features": ["4x optical zoom", "4MP resolution", "Preset patrol between points", "Ceiling or wall mount", "PoE + 12V DC"], "use_case": "Shops, offices, indoor overwatch", "recommended_for": "Indoor overwatch", "tech": {"resolution": "4MP", "zoom": "4x", "warranty": "2 years"}, "image_brief": "Small white PTZ mini dome camera hanging from a shop ceiling."}'::jsonb, ARRAY[]::text[], 245000, NULL, 100, 15, true, false, false),
  ('19588e06-3048-466b-b2bf-8c59ed68c1e0', 'PTZ 4MP 25x Outdoor', 'wf-ptz-4mp-25x', 'Zoom clear across a compound and read a plate.', '4MP outdoor PTZ with 25x optical zoom (100m+ face recognition). IP66 metal housing, 100m IR range, auto-tracking.', '{"hook_line": "Zoom clear across a compound and read a plate.", "features": ["25x optical zoom", "4MP with auto-track", "100m IR night vision", "IP66 metal housing", "PoE++ or 24V AC"], "use_case": "Compounds, gates, medium-range outdoor overwatch", "recommended_for": "Outdoor overwatch", "tech": {"resolution": "4MP", "zoom": "25x", "protection": "IP66", "warranty": "2 years"}, "image_brief": "White PTZ dome camera on a wall bracket overlooking a compound."}'::jsonb, ARRAY[]::text[], 680000, NULL, 50, 8, true, true, false),
  ('19588e06-3048-466b-b2bf-8c59ed68c1e0', 'PTZ 8MP 4K 32x', 'wf-ptz-8mp-4k-32x', 'Serious long-range PTZ — reads plates at 200m.', '4K PTZ with 32x optical zoom, auto-tracking, IP66 metal housing. Reads a licence plate at 200m in daylight.', '{"hook_line": "Serious long-range PTZ — reads plates at 200m.", "features": ["32x optical zoom", "8MP 4K sensor", "Auto human/vehicle tracking", "150m IR night vision", "IP66 metal housing"], "use_case": "Large compounds, industrial sites, ports", "recommended_for": "Long range", "tech": {"resolution": "8MP", "zoom": "32x", "protection": "IP66", "warranty": "2 years"}, "image_brief": "Large white outdoor PTZ camera mounted high on a pole overlooking an industrial site."}'::jsonb, ARRAY[]::text[], 1150000, NULL, 50, 5, true, true, false),
  ('19588e06-3048-466b-b2bf-8c59ed68c1e0', 'PTZ 2MP Laser Night PTZ', 'wf-ptz-2mp-laser', 'Sees clearly at 500m in total darkness thanks to laser IR.', '2MP starlight PTZ with 30x zoom and 500m laser IR. When you need to see a person a football field away with no streetlight.', '{"hook_line": "Sees clearly at 500m in total darkness thanks to laser IR.", "features": ["500m laser IR", "30x optical zoom", "2MP starlight sensor", "IP66 metal housing", "24V AC power"], "use_case": "Ports, borders, large yards after dark", "recommended_for": "Long-range at night", "tech": {"resolution": "2MP", "zoom": "30x", "ir_m": 500, "warranty": "3 years"}, "image_brief": "Large white PTZ camera on a tall pole with a visible laser illuminator port, at night."}'::jsonb, ARRAY[]::text[], 1450000, NULL, 100, 15, true, false, false),
  ('19588e06-3048-466b-b2bf-8c59ed68c1e0', 'PTZ 4MP Solar 4G', 'wf-ptz-solar-4g', 'Off-grid PTZ — panels + battery + 4G, one bundle.', '4MP PTZ, 4G modem, dual 100W solar panels and a 100Ah LiFePO4 battery. Preset patrol and phone control anywhere in Nigeria.', '{"hook_line": "Off-grid PTZ — panels + battery + 4G, one bundle.", "features": ["4G LTE built in", "Dual 100W solar + 100Ah", "Preset patrol between points", "IP66 metal housing", "20x optical zoom"], "use_case": "Farms, quarries, remote perimeter overwatch", "recommended_for": "Off-grid overwatch", "tech": {"resolution": "4MP", "zoom": "20x", "warranty": "2 years"}, "image_brief": "White PTZ on a tall pole with two solar panels above it and a battery box, at a remote site."}'::jsonb, ARRAY[]::text[], 1250000, NULL, 50, 4, true, true, false),
  ('19588e06-3048-466b-b2bf-8c59ed68c1e0', 'PTZ Panoramic + Detail Hybrid', 'wf-ptz-panoramic-hybrid', 'One 180° panoramic view PLUS a PTZ that auto-zooms into any motion.', 'Dual-form-factor camera: an 8MP panoramic 180° sensor cluster on top and a 25x PTZ below that auto-tracks anything the panoramic sees.', '{"hook_line": "One 180° panoramic view PLUS a PTZ that auto-zooms into any motion.", "features": ["180° panoramic 8MP", "25x optical PTZ below", "Auto-tracks motion in panoramic view", "Records both feeds", "IP66"], "use_case": "Estate gates, forecourts, main entrances", "recommended_for": "Estate gates", "tech": {"resolution": "8MP + 4MP", "zoom": "25x", "warranty": "2 years"}, "image_brief": "Dual-camera unit with a panoramic array on top and a PTZ dome below, on a tall pole."}'::jsonb, ARRAY[]::text[], 1850000, NULL, 30, 3, true, true, false),
  ('19588e06-3048-466b-b2bf-8c59ed68c1e0', 'PTZ Thermal + Optical', 'wf-ptz-thermal-ptz', 'Thermal detects, optical identifies — one unit does both.', 'Dual-sensor PTZ with a 384x288 thermal core and a 4MP 25x optical camera. Slews the optical onto any thermal detection automatically.', '{"hook_line": "Thermal detects, optical identifies — one unit does both.", "features": ["Thermal 384x288 sensor", "4MP 25x optical", "Detects person at 500m", "Auto-slew to thermal target", "IP67 metal housing"], "use_case": "Perimeters, oil depots, ports at night", "recommended_for": "Perimeters", "tech": {"resolution": "4MP + thermal", "zoom": "25x", "warranty": "3 years"}, "image_brief": "Large dual-lens PTZ camera on a heavy-duty pole with visible thermal and optical lens ports."}'::jsonb, ARRAY[]::text[], 3850000, NULL, 30, 2, true, false, false),
  ('19588e06-3048-466b-b2bf-8c59ed68c1e0', 'PTZ 4MP Explosion-Proof', 'wf-ptz-4mp-explosion', 'ATEX-rated PTZ for oil & gas plants.', '4MP 30x PTZ in a stainless-steel explosion-rated housing, ATEX/IECEx Zone 1. Fibre or PoE++ options.', '{"hook_line": "ATEX-rated PTZ for oil & gas plants.", "features": ["ATEX/IECEx Zone 1", "4MP 30x zoom", "316L stainless housing", "Fibre or PoE++", "IP68"], "use_case": "Oil & gas, chemical plants, refineries", "recommended_for": "Oil & gas", "tech": {"resolution": "4MP", "zoom": "30x", "certification": "ATEX Zone 1", "warranty": "5 years"}, "image_brief": "Heavy stainless-steel PTZ camera housing mounted on a refinery pipe."}'::jsonb, ARRAY[]::text[], 4650000, NULL, 30, 2, true, false, false),
  ('19588e06-3048-466b-b2bf-8c59ed68c1e0', 'PTZ Mini Speed Dome (Indoor)', 'wf-ptz-mini-speed-dome', 'Fast, quiet mini speed dome for indoor tracking.', 'Compact 4MP indoor speed dome with 10x zoom. Silent stepper motors — good for offices where a big whirring PTZ would annoy people.', '{"hook_line": "Fast, quiet mini speed dome for indoor tracking.", "features": ["10x optical zoom", "Silent stepper motors", "4MP resolution", "Ceiling flush mount", "PoE + 12V DC"], "use_case": "Offices, hotels, malls (indoor)", "recommended_for": "Indoor tracking", "tech": {"resolution": "4MP", "zoom": "10x", "warranty": "2 years"}, "image_brief": "Small silver ceiling-mounted PTZ speed dome in a hotel corridor."}'::jsonb, ARRAY[]::text[], 325000, NULL, 100, 15, true, false, false),
  ('19588e06-3048-466b-b2bf-8c59ed68c1e0', 'PTZ ANPR / LPR', 'wf-ptz-anpr-ptz', 'Slews onto vehicles as they arrive and reads the plate.', '5MP PTZ with dedicated ANPR firmware. Auto-slews onto approaching vehicles and captures the plate at up to 60 km/h. Whitelist alerts.', '{"hook_line": "Slews onto vehicles as they arrive and reads the plate.", "features": ["ANPR firmware built in", "Auto-slew to vehicles", "5MP with 25x zoom", "Blacklist/whitelist alerts", "IP66"], "use_case": "Estate gates, factories, toll points", "recommended_for": "Estate gates", "tech": {"resolution": "5MP", "zoom": "25x", "warranty": "2 years"}, "image_brief": "White PTZ camera on a boom over an estate gate with a car approaching below."}'::jsonb, ARRAY[]::text[], 1450000, NULL, 30, 3, true, false, false),
  ('19588e06-3048-466b-b2bf-8c59ed68c1e0', 'PTZ USB Joystick Controller', 'wf-ptz-controller-joystick', 'Three-axis joystick — control PTZs like a proper security desk.', 'USB joystick with a 3-axis handle, dedicated buttons for presets, patrols and iris. Works with all our NVRs and Windows VMS software.', '{"hook_line": "Three-axis joystick — control PTZs like a proper security desk.", "features": ["3-axis PTZ joystick", "Preset & patrol buttons", "USB plug-and-play", "Windows VMS support", "2-year warranty"], "use_case": "Guard desks, control rooms", "recommended_for": "Guard desks", "tech": {"axes": 3, "warranty": "2 years"}, "image_brief": "Black 3-axis joystick controller on a control-room desk in front of a video wall."}'::jsonb, ARRAY[]::text[], 95000, NULL, 100, 15, true, false, false),
  ('19588e06-3048-466b-b2bf-8c59ed68c1e0', 'PTZ 4MP with Wiper', 'wf-ptz-outdoor-wiper', 'Rain wiper on the lens — clear image during Lagos downpours.', '4MP outdoor PTZ with a small wiper blade on the front glass. Perfect for coastal and heavy-rain sites where droplets ruin normal PTZs.', '{"hook_line": "Rain wiper on the lens — clear image during Lagos downpours.", "features": ["Rain wiper on front glass", "4MP 25x zoom", "IP66 metal housing", "Auto human/vehicle tracking", "24V AC or PoE++"], "use_case": "Coastal sites and heavy-rain areas", "recommended_for": "Rainy sites", "tech": {"resolution": "4MP", "zoom": "25x", "warranty": "2 years"}, "image_brief": "White outdoor PTZ camera with a visible wiper blade across the front glass, mounted on a pole in rain."}'::jsonb, ARRAY[]::text[], 895000, NULL, 100, 15, true, false, false),
  ('19588e06-3048-466b-b2bf-8c59ed68c1e0', 'PTZ Rugged Mining PTZ', 'wf-ptz-rugged-mining', 'Built for dust, vibration and abuse.', 'IK10 vandal-rated PTZ in a heavy-duty aluminium housing. Anti-vibration mount, sealed IP67, wide temperature range. Made for mines and quarries.', '{"hook_line": "Built for dust, vibration and abuse.", "features": ["IK10 vandal rating", "4MP 30x zoom", "Anti-vibration mount", "-30 to +65°C operation", "Aluminium heavy housing"], "use_case": "Mines, quarries, ports", "recommended_for": "Mining & quarry", "tech": {"resolution": "4MP", "zoom": "30x", "protection": "IP67/IK10", "warranty": "3 years"}, "image_brief": "Grey heavy-duty PTZ camera mounted on an anti-vibration bracket at a quarry."}'::jsonb, ARRAY[]::text[], 1650000, NULL, 30, 2, true, false, false),
  ('19588e06-3048-466b-b2bf-8c59ed68c1e0', 'PTZ Corner Wall Mount', 'wf-ptz-mount-corner', 'Corner mount so your PTZ can see two walls, not just one.', 'Powder-coated corner wall mount adapter for our outdoor PTZs. Lets you place a PTZ on a building corner and cover two walls at once.', '{"hook_line": "Corner mount so your PTZ can see two walls, not just one.", "features": ["Powder-coated corner mount", "Cable channel", "Fits all WF outdoor PTZs", "Base plate + fixings", "2 year warranty"], "use_case": "PTZ installs at building corners", "recommended_for": "Corner installs", "tech": {"warranty": "2 years"}, "image_brief": "Grey powder-coated PTZ corner-mount bracket on a workbench next to a PTZ."}'::jsonb, ARRAY[]::text[], 42000, NULL, 100, 15, true, false, false),
  ('19588e06-3048-466b-b2bf-8c59ed68c1e0', 'PTZ Perimeter Kit — 2 PTZ + Radar', 'wf-ptz-kit-perimeter', 'Two PTZs and a radar sensor for automated perimeter overwatch.', 'Two 4MP 25x PTZs plus one 100m radar that auto-slews the PTZs onto detected motion. Preconfigured — ships ready to mount.', '{"hook_line": "Two PTZs and a radar sensor for automated perimeter overwatch.", "features": ["2x 4MP 25x PTZs", "1x 100m 24GHz radar", "Radar auto-slews the PTZs", "Central controller", "Ships pre-configured"], "use_case": "Small-to-medium perimeter overwatch", "recommended_for": "Perimeters", "tech": {"cameras": 2, "radar_m": 100, "warranty": "2 years"}, "image_brief": "Flat-lay of two white PTZ cameras and a rectangular radar unit with cables on a workbench."}'::jsonb, ARRAY[]::text[], 2450000, NULL, 30, 2, true, true, false),
  ('4201a94e-465b-43ff-b108-c53b4d8951de', 'Doorbell 2MP WiFi', 'wf-vdb-2mp-wifi', 'Simple WiFi doorbell — chime in your pocket, not on the wall.', 'Battery+wired 2MP video doorbell with two-way talk, motion detection and phone push alerts. Chime plugs into any wall socket.', '{"hook_line": "Simple WiFi doorbell — chime in your pocket, not on the wall.", "features": ["2MP video + two-way audio", "Battery or hardwired", "Wireless chime included", "Free cloud clip storage (7 days)", "IP65"], "use_case": "Homes and small offices with WiFi", "recommended_for": "Homes", "tech": {"resolution": "2MP", "warranty": "2 years"}, "image_brief": "Small black video doorbell mounted beside a wooden front door."}'::jsonb, ARRAY[]::text[], 68000, NULL, 100, 15, true, true, false),
  ('4201a94e-465b-43ff-b108-c53b4d8951de', 'Doorbell 2K WiFi', 'wf-vdb-2k-wifi', 'Sharp enough to see who''s really at the door.', '2K resolution video doorbell with better low-light performance, a wider 160° lens and no monthly fee for local SD recording.', '{"hook_line": "Sharp enough to see who''s really at the door.", "features": ["2K sharper video", "160° wide lens", "Local SD recording, no fee", "Two-way talk + siren", "IP65"], "use_case": "Homes wanting to see the whole doorway clearly", "recommended_for": "Homes", "tech": {"resolution": "2K", "fov": "160°", "warranty": "2 years"}, "image_brief": "Slim black video doorbell with a wide-angle lens beside a modern front door."}'::jsonb, ARRAY[]::text[], 95000, NULL, 100, 15, true, false, false),
  ('4201a94e-465b-43ff-b108-c53b4d8951de', 'Doorbell 4MP IP PoE', 'wf-vdb-4mp-ip-poe', 'PoE video doorbell that records straight to your NVR.', '4MP IP doorbell with PoE — records straight to your existing NVR alongside your CCTV. No cloud, no app account, no subscription.', '{"hook_line": "PoE video doorbell that records straight to your NVR.", "features": ["4MP video, records to NVR", "PoE — one Cat6 does everything", "Two-way audio", "No cloud account needed", "ONVIF"], "use_case": "Homes and offices already running an IP NVR", "recommended_for": "NVR sites", "tech": {"resolution": "4MP", "warranty": "2 years"}, "image_brief": "White PoE doorbell camera beside a front door, with a Cat6 cable visible."}'::jsonb, ARRAY[]::text[], 145000, NULL, 100, 15, true, false, false),
  ('4201a94e-465b-43ff-b108-c53b4d8951de', 'Doorbell 3MP Battery', 'wf-vdb-3mp-battery', 'No wiring — runs six months on a charge.', 'Fully wireless 3MP doorbell with a rechargeable 5000mAh battery. Six months typical use per charge. Great for rentals where you can''t drill.', '{"hook_line": "No wiring — runs six months on a charge.", "features": ["No wiring at all", "5000mAh battery, ~6 months", "3MP video + two-way talk", "WiFi + wireless chime", "IP65"], "use_case": "Rentals, apartments, no-wiring installs", "recommended_for": "Rentals", "tech": {"resolution": "3MP", "battery_mah": 5000, "warranty": "2 years"}, "image_brief": "Small white wireless doorbell magnetically attached beside a rental apartment door."}'::jsonb, ARRAY[]::text[], 78000, NULL, 100, 15, true, false, false),
  ('4201a94e-465b-43ff-b108-c53b4d8951de', 'Doorbell Dual-Lens Head-to-Toe', 'wf-vdb-dual-lens', 'Two lenses — one for face, one for the parcel on the doormat.', 'Dual-lens video doorbell: one wide lens for face recognition, one downward-angle lens to see parcels and dogs. Both stream simultaneously.', '{"hook_line": "Two lenses — one for face, one for the parcel on the doormat.", "features": ["Dual lens: face + package", "2K wide + 1080p down", "Package alerts", "Two-way talk", "IP65"], "use_case": "Homes with regular deliveries", "recommended_for": "Deliveries", "tech": {"resolution": "2K + 1080p", "warranty": "2 years"}, "image_brief": "Slim black video doorbell with two visible lens circles, beside a front door with a package on the mat."}'::jsonb, ARRAY[]::text[], 165000, NULL, 100, 15, true, false, false),
  ('4201a94e-465b-43ff-b108-c53b4d8951de', 'Doorbell 4MP Face-Recognition', 'wf-vdb-face-recog', 'Learns your family — and tells you when a stranger arrives.', '4MP doorbell with on-device face recognition. Silent for known faces, alert for unknowns. Records to SD or NVR, no cloud required.', '{"hook_line": "Learns your family — and tells you when a stranger arrives.", "features": ["On-device face recognition", "Silent for known faces", "4MP video + two-way audio", "SD or NVR recording", "IP65"], "use_case": "Homes wanting smarter alerts", "recommended_for": "Smarter homes", "tech": {"resolution": "4MP", "warranty": "2 years"}, "image_brief": "Black slim video doorbell with a visible IR sensor and lens, beside a modern front door."}'::jsonb, ARRAY[]::text[], 195000, NULL, 50, 10, true, false, false),
  ('4201a94e-465b-43ff-b108-c53b4d8951de', 'Doorbell 4-Unit Intercom', 'wf-vdb-intercom-4-unit', 'Four-flat intercom system — one door, four handsets.', 'IP intercom video doorbell with 4 indoor screens (7-inch) — one per flat. Records visitors to a shared NVR. Unlock relay for a shared front gate.', '{"hook_line": "Four-flat intercom system — one door, four handsets.", "features": ["1 door station + 4 screens", "7-inch indoor monitors", "Unlock relay for gate/door", "Records to shared NVR", "PoE + local backup"], "use_case": "4-flat buildings with a shared front door", "recommended_for": "Multi-unit buildings", "tech": {"stations": 1, "screens": 4, "warranty": "2 years"}, "image_brief": "Slim silver door station with a screen and buttons, mounted beside a shared apartment entrance."}'::jsonb, ARRAY[]::text[], 485000, NULL, 100, 15, true, false, false),
  ('4201a94e-465b-43ff-b108-c53b4d8951de', 'Doorbell 8-Unit Intercom', 'wf-vdb-intercom-8-unit', 'Eight-flat intercom with tenant-selectable calling.', 'IP intercom with a directory pad that lets visitors call any of 8 flats. Comes with 8 indoor screens and a shared unlock relay. Records to NVR.', '{"hook_line": "Eight-flat intercom with tenant-selectable calling.", "features": ["Directory-pad calls any flat", "8 indoor 7-inch monitors", "Unlock relay", "Records to NVR", "PoE + backup power"], "use_case": "8-unit apartment blocks", "recommended_for": "Apartments", "tech": {"stations": 1, "screens": 8, "warranty": "2 years"}, "image_brief": "Larger silver door station with a directory keypad and screen, mounted beside an apartment entrance."}'::jsonb, ARRAY[]::text[], 895000, NULL, 30, 3, true, false, false),
  ('4201a94e-465b-43ff-b108-c53b4d8951de', 'Doorbell Vandal-Proof Video', 'wf-vdb-anti-vandal', 'Metal doorbell for tough neighbourhoods and public entries.', 'IK10 vandal-rated metal video doorbell — screwed flush, no removable parts. 2MP video + two-way talk. Great for offices and public buildings.', '{"hook_line": "Metal doorbell for tough neighbourhoods and public entries.", "features": ["IK10 vandal rating", "Flush metal housing", "2MP + two-way audio", "PoE", "IP66"], "use_case": "Offices, public buildings, high-risk streets", "recommended_for": "Public buildings", "tech": {"resolution": "2MP", "protection": "IP66/IK10", "warranty": "3 years"}, "image_brief": "Flush metal video doorbell recessed into a concrete wall beside a heavy office door."}'::jsonb, ARRAY[]::text[], 125000, NULL, 100, 15, true, false, false),
  ('4201a94e-465b-43ff-b108-c53b4d8951de', 'Doorbell Solar Battery', 'wf-vdb-solar-battery', 'Solar-topped battery doorbell — never charge it again.', 'Battery video doorbell with a matching mini solar panel (mount above the door). Trickle-charges through daylight so the battery never runs out.', '{"hook_line": "Solar-topped battery doorbell — never charge it again.", "features": ["Battery + solar top-up", "Never manually charge", "3MP video + two-way audio", "WiFi + wireless chime", "IP65"], "use_case": "Homes with a bright front door area", "recommended_for": "Sunny doors", "tech": {"resolution": "3MP", "warranty": "2 years"}, "image_brief": "Battery video doorbell with a small solar panel mounted above it on a sunny porch."}'::jsonb, ARRAY[]::text[], 115000, NULL, 100, 15, true, false, false),
  ('4201a94e-465b-43ff-b108-c53b4d8951de', 'Doorbell 7-inch Indoor Monitor', 'wf-vdb-large-screen-7in', 'Big colourful screen for the hallway — see who''s at the door across the room.', '7-inch colour touch screen indoor monitor for our IP doorbells. Wall-mount, PoE-powered, records snapshots of every ring.', '{"hook_line": "Big colourful screen for the hallway — see who''s at the door across the room.", "features": ["7-inch colour touch screen", "PoE powered", "Records visitor snapshots", "Wall mount included", "Ties to any WF IP doorbell"], "use_case": "Adding an extra indoor screen to a doorbell install", "recommended_for": "Indoor screens", "tech": {"screen_in": 7, "warranty": "2 years"}, "image_brief": "Wall-mounted 7-inch colour touchscreen showing a doorway image in a home hallway."}'::jsonb, ARRAY[]::text[], 78000, NULL, 100, 15, true, false, false),
  ('4201a94e-465b-43ff-b108-c53b4d8951de', 'Doorbell 10-inch Indoor Monitor', 'wf-vdb-large-screen-10in', 'Big 10-inch screen for the main hallway or reception.', '10-inch indoor monitor for our IP doorbell system. Wall-mount, PoE, records snapshots, supports 4 door stations.', '{"hook_line": "Big 10-inch screen for the main hallway or reception.", "features": ["10-inch colour touch screen", "Supports up to 4 door stations", "PoE powered", "Records visitor snapshots", "Wall mount included"], "use_case": "Main halls, receptions, security desks", "recommended_for": "Reception screens", "tech": {"screen_in": 10, "warranty": "2 years"}, "image_brief": "Wall-mounted 10-inch colour touchscreen on a reception wall showing a doorway feed."}'::jsonb, ARRAY[]::text[], 195000, NULL, 100, 15, true, false, false),
  ('4201a94e-465b-43ff-b108-c53b4d8951de', 'Doorbell Wireless Unlock Relay', 'wf-vdb-relay-unlock', 'Adds a remote-unlock relay to any of our doorbells.', 'Wireless 12V relay that pairs with any WF video doorbell — tap the app to unlock a gate or door remotely. Fits behind a maglock or strike lock.', '{"hook_line": "Adds a remote-unlock relay to any of our doorbells.", "features": ["12V relay for gate/door", "Pairs with any WF doorbell", "Remote unlock from the app", "Fits maglocks and strike locks", "2 year warranty"], "use_case": "Adding remote unlock to a doorbell install", "recommended_for": "Remote unlock", "tech": {"voltage": "12V", "warranty": "2 years"}, "image_brief": "Small black wireless relay unit next to an electric strike lock on a workbench."}'::jsonb, ARRAY[]::text[], 45000, NULL, 100, 15, true, false, false),
  ('4201a94e-465b-43ff-b108-c53b4d8951de', 'Doorbell Package-Locker Camera', 'wf-vdb-package-locker-cam', 'Discreet 2nd camera aimed at your parcel drop-box.', 'Small companion camera for our video doorbells — mount it in a parcel locker or above a doormat. Streams into the same doorbell app.', '{"hook_line": "Discreet 2nd camera aimed at your parcel drop-box.", "features": ["Companion parcel-view camera", "2MP wide-angle lens", "Pairs with WF doorbells", "Battery or WiFi", "IP65"], "use_case": "Homes with a delivery locker or drop-mat", "recommended_for": "Delivery zones", "tech": {"resolution": "2MP", "warranty": "2 years"}, "image_brief": "Small white companion camera aimed down into a delivery locker at a front porch."}'::jsonb, ARRAY[]::text[], 68000, NULL, 100, 15, true, false, false),
  ('4201a94e-465b-43ff-b108-c53b4d8951de', 'Doorbell Complete Home Kit', 'wf-vdb-kit-home', 'Doorbell + 7-inch indoor monitor + gate relay in one box.', 'Everything a family needs: our 4MP PoE doorbell, one 7-inch indoor screen and a wireless unlock relay for the front gate. Pre-linked, ready to install.', '{"hook_line": "Doorbell + 7-inch indoor monitor + gate relay in one box.", "features": ["4MP PoE video doorbell", "7-inch indoor touchscreen", "Wireless gate unlock relay", "All fixings & short cables", "Free remote setup"], "use_case": "Homes wanting one boxed doorbell solution", "recommended_for": "Family homes", "tech": {"warranty": "2 years"}, "image_brief": "Flat-lay of a video doorbell, an indoor touchscreen and a small relay unit with cables on a workbench."}'::jsonb, ARRAY[]::text[], 295000, NULL, 50, 8, true, true, false)
